const N = 2 * PATCH_R + 1, NN = N * N;
const EMPTY = STATES.indexOf('empty');
interface CampTemplates {
  /** per state: RGB patch variants (the icon rendering differs slightly between game phases) */
  patch: Float32Array[][];
  /** per state, per variant: icon pixels (differ from the empty floor) */
  mask: Uint8Array[][];
  /** union of all icon masks: where the empty-floor comparison is made */
  union: Uint8Array;
}
const templateCache = new Map<number, CampTemplates[]>();

/**
 * 1-D model of the bilinear pipeline "game draws the minimap at W px" -> resize(W -> 341) for samples
 * `v` at 341-grid coords x0..x0+v.length-1 (the game image at W is approximated by resampling 341 -> W).
 * Uses the same pixel-center convention as png.ts resize, so the phase matches the real frame.
 */
function resample1d(v: Float64Array, x0: number, W: number): Float64Array {
  const n = v.length, S = 341;
  const at = (f: number) => { const g = Math.min(n - 1, Math.max(0, f - x0)), i = Math.floor(g), t = g - i; return v[i]! * (1 - t) + v[Math.min(n - 1, i + 1)]! * t; };
  const u0 = Math.max(0, Math.floor(((x0 - 1 + 0.5) * W) / S - 0.5) - 1), u1 = Math.min(W - 1, Math.ceil(((x0 + n + 0.5) * W) / S) + 1);
  const mid = new Float64Array(u1 - u0 + 1);
  for (let u = u0; u <= u1; u++) mid[u - u0] = at(Math.max(0, ((u + 0.5) * S) / W - 0.5));
  const out = new Float64Array(n);
  for (let k = 0; k < n; k++) {
    const fu = Math.max(0, ((x0 + k + 0.5) * W) / S - 0.5), i = Math.floor(fu), t = fu - i;
    const m = (j: number) => mid[Math.min(u1, Math.max(u0, j)) - u0]!;
    out[k] = m(i) * (1 - t) + m(Math.min(W - 1, i + 1)) * t;
  }
  return out;
}

/** Template patch (centered at 341-grid px cx0,cy0) as it looks after a srcWidth crop is resized to 341. */
function simulateResize(p: Float32Array, cx0: number, cy0: number, srcWidth: number): Float32Array {
  if (srcWidth === 341) return p;
  const out = new Float32Array(NN * 3), tmp = new Float64Array(NN * 3), line = new Float64Array(N);
  for (let ch = 0; ch < 3; ch++) {
    for (let y = 0; y < N; y++) { for (let x = 0; x < N; x++) line[x] = p[(y * N + x) * 3 + ch]!; const r = resample1d(line, cx0 - PATCH_R, srcWidth); for (let x = 0; x < N; x++) tmp[(y * N + x) * 3 + ch] = r[x]!; }
    for (let x = 0; x < N; x++) { for (let y = 0; y < N; y++) line[y] = tmp[(y * N + x) * 3 + ch]!; const r = resample1d(line, cy0 - PATCH_R, srcWidth); for (let y = 0; y < N; y++) out[(y * N + x) * 3 + ch] = r[y]!; }
  }
  return out;
}

/** Templates for frames originally `srcWidth` px wide (cached per width). */
function getTemplates(srcWidth = 341): CampTemplates[] {
  const hit = templateCache.get(srcWidth);
  if (hit) return hit;
  const maskOf = (p: Float32Array, e: Float32Array) => {
    const m = new Uint8Array(NN);
    for (let i = 0; i < NN; i++) {
      const d = Math.max(Math.abs(p[i * 3]! - e[i * 3]!), Math.abs(p[i * 3 + 1]! - e[i * 3 + 1]!), Math.abs(p[i * 3 + 2]! - e[i * 3 + 2]!));
      if (d > 30) m[i] = 1;
    }
    return m;
  };
  const orUnion = (t: CampTemplates) => { for (const list of t.mask) for (const m of list) for (let i = 0; i < NN; i++) if (m[i]) t.union[i] = 1; };
  let ts: CampTemplates[];
  if (srcWidth === 341) {
    const raw = Buffer.from(TEMPLATE_DATA, 'base64');
    let o = 0;
    ts = CAMPS.map(() => ({
      patch: STATES.map(() => {
        const n = raw[o++]!, list: Float32Array[] = [];
        for (let v = 0; v < n; v++) { list.push(Float32Array.from(raw.subarray(o, o + NN * 3))); o += NN * 3; }
        return list;
      }),
      mask: [], union: new Uint8Array(NN),
    }));
    if (o !== raw.length) throw new Error('camps: bad template data');
    // States never observed for a camp borrow the icon of a camp of the same kind.
    for (let k = 0; k < CAMPS.length; k++) for (let s = 0; s < STATES.length; s++) {
      if (ts[k]!.patch[s]!.length) continue;
      const donor = ts.findIndex((t, j) => CAMPS[j]!.kind === CAMPS[k]!.kind && t.patch[s]!.length);
      if (donor >= 0) ts[k]!.patch[s] = ts[donor]!.patch[s]!;
    }
    for (const t of ts) { const e = t.patch[EMPTY]![0]!; t.mask = t.patch.map((list, s) => (s === EMPTY ? [] : list.map(p => maskOf(p, e)))); orUnion(t); }
  } else {
    // Other crop sizes: model the resampling blur at each camp's exact phase. The blur mixes the floor into
    // the icon edge, and fog darkens the floor, so every icon variant gets a clear-floor and a fogged-floor copy.
    const FOG = 0.36;
    ts = getTemplates(341).map((nt, k) => {
      const c = CAMPS[k]!, cx0 = Math.round(c.x * 341), cy0 = Math.round(c.y * 341);
      const e = simulateResize(nt.patch[EMPTY]![0]!, cx0, cy0, srcWidth);
      const t: CampTemplates = { patch: [], mask: [], union: new Uint8Array(NN) };
      STATES.forEach((_st, s) => {
        if (s === EMPTY) { t.patch.push([e]); t.mask.push([]); return; }
        const pl: Float32Array[] = [], ml: Uint8Array[] = [];
        nt.patch[s]!.forEach((p, v) => {
          const nm = nt.mask[s]![v]!, fogged = Float32Array.from(p);
          for (let i = 0; i < NN; i++) if (!nm[i]) for (let ch = 0; ch < 3; ch++) fogged[i * 3 + ch]! *= FOG;
          const clear = simulateResize(p, cx0, cy0, srcWidth), m = maskOf(clear, e);
          pl.push(clear, simulateResize(fogged, cx0, cy0, srcWidth)); ml.push(m, m);
        });
        t.patch.push(pl); t.mask.push(ml);
      });
      orUnion(t);
      return t;
    });
  }
  templateCache.set(srcWidth, ts);
  return ts;
}

/** Robust mean absolute difference: average over the best 85% of masked pixels (tolerates small pings/wards). */
function trimmedDist(buf: Float32Array, n: number): number {
  const a = buf.subarray(0, n).sort();
  const keep = Math.max(1, Math.round(n * 0.85));
  let s = 0;
  for (let i = 0; i < keep; i++) s += a[i]!;
  return s / keep;
}

const scratch = new Float32Array(NN);

/**
 * Per-state distance (mean abs RGB difference, 0..255; order of STATES) of the frame around camp k.
 * `frame` must be the 341 px crop (`srcWidth` = its width before resizing to 341). Icon templates are searched ±`shift` px; the empty floor is
 * compared in place with a fitted brightness factor (the fog overlay darkens the floor, not icons).
 */
export function campDistances(frame: Rgba, k: number, shift = 1, srcWidth = 341): number[] {
  const t = getTemplates(srcWidth)[k]!, c = CAMPS[k]!, W = frame.width, d = frame.data;
  const cx0 = Math.round(c.x * 341), cy0 = Math.round(c.y * 341);
  const out = STATES.map(() => Infinity);
  const at = (ox: number, oy: number, i: number) => ((oy + ((i / N) | 0)) * W + ox + (i % N)) * 4;
  for (let dy = -shift; dy <= shift; dy++) for (let dx = -shift; dx <= shift; dx++) {
    const ox = cx0 - PATCH_R + dx, oy = cy0 - PATCH_R + dy;
    if (ox < 0 || oy < 0 || ox + N > W || oy + N > frame.height) continue;
    for (let s = 0; s < STATES.length; s++) {
      if (s === EMPTY) {
        const p = t.patch[s]![0];
        if (!p || dx || dy) continue; // the floor does not move
        let pr = 0, rr = 0;
        for (let i = 0; i < NN; i++) if (t.union[i]) {
          const q = at(ox, oy, i);
          for (let ch = 0; ch < 3; ch++) { pr += d[q + ch]! * p[i * 3 + ch]!; rr += p[i * 3 + ch]! * p[i * 3 + ch]!; }
        }
        const f = rr > 0 ? Math.min(1.05, Math.max(0.3, pr / rr)) : 1;
        let n = 0;
        for (let i = 0; i < NN; i++) if (t.union[i]) {
          const q = at(ox, oy, i);
          scratch[n++] = (Math.abs(d[q]! - f * p[i * 3]!) + Math.abs(d[q + 1]! - f * p[i * 3 + 1]!) + Math.abs(d[q + 2]! - f * p[i * 3 + 2]!)) / 3;
        }
        if (n) out[s] = Math.min(out[s]!, trimmedDist(scratch, n));
        continue;
      }
      const list = t.patch[s]!;
      for (let v = 0; v < list.length; v++) {
        const p = list[v]!, m = t.mask[s]![v]!;
        let n = 0;
        for (let i = 0; i < NN; i++) if (m[i]) {
          const q = at(ox, oy, i);
          scratch[n++] = (Math.abs(d[q]! - p[i * 3]!) + Math.abs(d[q + 1]! - p[i * 3 + 1]!) + Math.abs(d[q + 2]! - p[i * 3 + 2]!)) / 3;
        }
        if (n) out[s] = Math.min(out[s]!, trimmedDist(scratch, n));
      }
    }
  }
  return out;
}

/** What the minimap draws at a camp. */
export type CampIconState = 'up' | 'respawning' | 'respawn_soon' | 'empty';
const ICON_OF: Record<typeof STATES[number], CampIconState> = { up: 'up', grey: 'respawning', yellow: 'respawn_soon', empty: 'empty' };

export interface CampReading {
  id: string;
  side: CampSide;
  /** true = camp icon drawn (alive); false = no live icon (cleared / respawning / not spawned); null = can't tell (occluded by a champion icon, ping, camera box...) */
  present: boolean | null;
  /** detailed icon; null when occluded */
  icon: CampIconState | null;
  confidence: number;
}

/** maxDist: per-state acceptance threshold (order of STATES: up, grey, yellow, empty); minMargin: required gap to the runner-up. */
export interface ReadCampsParams { maxDist: [number, number, number, number]; minMargin: number }
// Empty is strict: a translucent ping or a champion edge over the floor scores 15-25, a bare floor (fogged or not) < 9.
export const DEFAULT_CAMP_PARAMS: ReadCampsParams = { maxDist: [16, 16, 16, 12], minMargin: 6 };

/**
 * Read every camp icon on a minimap crop (any square size; internally compared at the 341 px the
 * templates were captured at). Icons: orange diamond / brown claw (buffs) = up, grey hourglass =
 * respawning (last 30 s; scuttle last 60 s), yellow hourglass = respawning in ≤10 s, nothing = cleared
 * (or not yet spawned). `reference` is accepted for API symmetry with fog.ts but unused: the shipped
 * reference texture has the camp icons baked in, so per-camp empty-floor templates are used instead.
 */
export function readCamps(frame: Rgba, _reference?: Rgba, params: ReadCampsParams = DEFAULT_CAMP_PARAMS): CampReading[] {
  const img = frame.width === 341 && frame.height === 341 ? frame : resizeTo341(frame);
  return CAMPS.map((c, k) => {
    const d = campDistances(img, k, 1, frame.width);
    const order = d.map((v, i) => [v, i] as const).sort((a, b) => a[0] - b[0]);
    const [d1, s1] = order[0]!, d2 = order[1]![0];
    const max = params.maxDist[s1]!;
    const ok = d1 < max && d2 - d1 > params.minMargin;
    const confidence = ok ? Math.round(Math.min(1, (d2 - d1) / 20) * Math.min(1, (max + 4 - d1) / 12) * 100) / 100 : 0;
    if (!ok) return { id: c.id, side: c.side, present: null, icon: null, confidence };
    const icon = ICON_OF[STATES[s1]!];
    return { id: c.id, side: c.side, present: icon === 'up', icon, confidence };
  });
}

function resizeTo341(frame: Rgba): Rgba { return resize(frame, 341, 341); }

// ---------------------------------------------------------------------------------------------
// Tracker

export type CampState = 'up' | 'down' | 'unknown';
export interface CampStatus { id: string; side: CampSide; state: CampState; downSince: number | null; respawnAt: number | null }
export interface CampEvent {
  id: string; side: CampSide; at: number;
  /** cleared: live icon vanished (at = first frame without it). respawned: icon back.
   *  retracted: an earlier 'cleared' was not followed by the respawn hourglass on schedule (treat it as wrong). */
  kind: 'cleared' | 'respawned' | 'retracted';
  /** for 'cleared': expected respawn time (s) */
  respawnAt?: number;
  /** for 'cleared': last time the live icon was actually seen. The camp died in [earliest, at]; the gap is
   *  large when a portrait or a (red-team) ward covered the camp right after the kill. */
  earliest?: number;
}
export interface CampTrackerOptions {
  /** consecutive identical readings needed before an icon change is accepted */
  minFrames: number;
  /** ...spanning at least this many seconds */
  minSec: number;
  /** P(visible) at/above which a camp location counts as in vision (only used with visibleFn) */
  visibleThreshold: number;
}
export const DEFAULT_TRACKER_OPTIONS: CampTrackerOptions = { minFrames: 3, minSec: 1, visibleThreshold: 0.6 };

/** Seconds before respawn at which the grey / yellow hourglass appears (measured on a 2026 replay). */
export const greyLead = (c: CampDef): number => (c.kind === 'scuttle' ? 60 : 30);
export const YELLOW_LEAD = 10;

interface Track {
  def: CampDef;
  stable: CampIconState | null;
  cand: CampIconState | null; candSince: number; candCount: number; candVisible: boolean;
  /** time of the last raw 'up' reading */
  lastUp: number | null;
  state: CampState; downSince: number | null; respawnAt: number | null;
  /** respawnAt came from a 'cleared' inference and still awaits the hourglass that confirms it */
  pendingConfirm: boolean;
}

const freshTrack = (def: CampDef): Track => ({ def, stable: null, cand: null, candSince: 0, candCount: 0, candVisible: false, lastUp: null, state: 'unknown', downSince: null, respawnAt: null, pendingConfirm: false });

/**
 * Turns per-frame camp readings into debounced camp states, clear events and respawn times.
 *
 * Semantics (measured on a 39-min replay, see scripts/dev/camps-eval.ts):
 * - jungle camp icons (incl. hourglasses) are drawn regardless of fog; a live icon vanishing = camp died.
 * - scuttle "up" icons are only drawn while the crab is in vision (its hourglasses are global), so a
 *   scuttle icon vanishing counts as a clear only while the spot is visible (requires visibleFn).
 * - with a visibleFn, vanishing icons inside fog are trusted only once some camp icon has been seen
 *   drawn inside fog (guards against a client that hides fogged camps).
 * - every clear must be followed by the grey hourglass at respawnAt-30 s; if not, a 'retracted' event.
 */
export class CampTracker {
  readonly events: CampEvent[] = [];
  private tracks: Track[];
  private opts: CampTrackerOptions;
  /** null = not yet known whether icons are drawn inside fog */
  private iconsInFog: boolean | null = null;
  private fogIconFrames = 0;

  constructor(opts: Partial<CampTrackerOptions> = {}) {
    this.opts = { ...DEFAULT_TRACKER_OPTIONS, ...opts };
    this.tracks = CAMPS.map(freshTrack);
  }

  reset(): void {
    this.events.length = 0; this.iconsInFog = null; this.fogIconFrames = 0;
    this.tracks = CAMPS.map(freshTrack);
  }

  /**
   * @param gameTimeSec game clock of the frame (seconds)
   * @param readings output of readCamps for that frame
   * @param visibleFn optional P(visible) at normalized minimap coords (e.g. from readVisionMask)
   * @returns current status of every camp; new events are appended to `this.events`
   */
  update(gameTimeSec: number, readings: CampReading[], visibleFn?: (x: number, y: number) => number): CampStatus[] {
    const byId = new Map(readings.map(r => [r.id, r]));
    let fogIcon = false;
    for (const t of this.tracks) {
      const r = byId.get(t.def.id);
      const vis = visibleFn ? visibleFn(t.def.x, t.def.y) >= this.opts.visibleThreshold : true;
      if (r && r.icon) {
        if (r.icon === 'up') t.lastUp = gameTimeSec;
        if (visibleFn && !vis && r.icon !== 'empty' && t.def.kind !== 'scuttle') fogIcon = true;
        if (r.icon === t.cand) { t.candCount++; t.candVisible = t.candVisible && vis; }
        else { t.cand = r.icon; t.candSince = gameTimeSec; t.candCount = 1; t.candVisible = vis; }
        if (t.cand !== t.stable && t.candCount >= this.opts.minFrames && gameTimeSec - t.candSince >= this.opts.minSec) this.accept(t, t.cand, t.candSince, t.candVisible, visibleFn !== undefined);
      }
      this.expire(t, gameTimeSec);
    }
    if (visibleFn && this.iconsInFog === null) { this.fogIconFrames = fogIcon ? this.fogIconFrames + 1 : 0; if (this.fogIconFrames >= 3) this.iconsInFog = true; }
    return this.status();
  }

  status(): CampStatus[] {
    return this.tracks.map(t => ({ id: t.def.id, side: t.def.side, state: t.state, downSince: t.downSince, respawnAt: t.respawnAt }));
  }

  private accept(t: Track, icon: CampIconState, since: number, visibleThroughout: boolean, haveVision: boolean): void {
    const prev = t.stable, c = t.def;
    t.stable = icon;
    switch (icon) {
      case 'up':
        if (t.state === 'down') this.events.push({ id: c.id, side: c.side, at: since, kind: 'respawned' });
        t.state = 'up'; t.downSince = null; t.respawnAt = null; t.pendingConfirm = false;
        break;
      case 'respawning':
      case 'respawn_soon': {
        const at = since + (icon === 'respawning' ? greyLead(c) : YELLOW_LEAD);
        // Seeing the icon appear (prev known) pins the respawn time; a first sighting mid-phase is only a bound.
        const pinned = prev !== null;
        if (pinned || t.respawnAt === null || t.pendingConfirm) t.respawnAt = at;
        // The hourglass schedule also tells exactly when the camp died (more precise than the vanishing icon).
        if (c.kind !== 'scuttle' && (t.downSince === null || (pinned && icon === 'respawning'))) t.downSince = t.respawnAt - c.respawnSec;
        t.state = 'down'; t.pendingConfirm = false;
        break;
      }
      case 'empty':
        if (prev === 'up') {
          const trust = c.kind === 'scuttle'
            ? haveVision && visibleThroughout
            : !haveVision || visibleThroughout || this.iconsInFog === true;
          if (trust) {
            // Scuttle respawn is not a fixed delay after its kill (5:40-7:00 observed): wait for its hourglass.
            t.state = 'down'; t.downSince = since; t.respawnAt = c.kind === 'scuttle' ? null : since + c.respawnSec; t.pendingConfirm = c.kind !== 'scuttle';
            this.events.push({ id: c.id, side: c.side, at: since, kind: 'cleared', ...(t.respawnAt !== null ? { respawnAt: t.respawnAt } : {}), earliest: t.lastUp ?? since });
          } else { t.state = 'unknown'; t.downSince = null; t.respawnAt = null; t.pendingConfirm = false; }
        } else if (prev === null) t.state = 'unknown';
        // hourglass -> empty does not happen in practice; keep the current state.
        break;
    }
  }

  /** A cleared camp must show its hourglass on schedule; if it doesn't, retract the clear. */
  private expire(t: Track, now: number): void {
    if (t.state !== 'down' || t.respawnAt === null) return;
    if (t.pendingConfirm && t.stable === 'empty' && now > t.respawnAt - greyLead(t.def) + 15) {
      this.events.push({ id: t.def.id, side: t.def.side, at: now, kind: 'retracted' });
      t.state = 'unknown'; t.downSince = null; t.respawnAt = null; t.pendingConfirm = false;
    } else if (!t.pendingConfirm && now > t.respawnAt + 20 && t.stable !== 'up') {
      // Hourglass ran out but no live icon for 20 s (occluded the whole time?): don't guess.
      t.state = 'unknown'; t.downSince = null; t.respawnAt = null;
    }
  }
}
